update edu_review
total_score = #{totalScore}, review_comment = #{reviewComment}, status = #{status}, review_time = #{reviewTime}, publish_time = #{publishTime}, return_reason = #{returnReason}, return_deadline = #{returnDeadline}, is_return = #{isReturn}, update_time = sysdate()
