mapper.select:
select tk.task_id as taskId, tk.title as taskTitle, c.course_name as courseName, (select count(1) from edu_task_participant p where p.task_id = tk.task_id) as participantCount, (select count(1) from edu_submission s where s.task_id = tk.task_id and s.status = 2) as pendingCount, (select count(1) from edu_submission s where s.task_id = tk.task_id and s.status = 3) as reviewedCount, (select count(1) from edu_submission s where s.task_id = tk.task_id and s.status = 5) as overdueCount from edu_task tk left join edu_course c on c.course_id = tk.course_id
tk.del_flag = '0' and tk.status in (1, 2, 4) and tk.course_id = #{courseId}
order by tk.deadline desc
